using VinayakaAgencies.Application.Common;using VinayakaAgencies.Application.Gst;using VinayakaAgencies.Application.Tests.TestDoubles;using VinayakaAgencies.Domain.Gst;using Shouldly;namespace VinayakaAgencies.Application.Tests.Gst;/// <summary>/// Rate resolution by effective date (phase-5-gst-returns.md §2, checkpoint C5.5): a rate change/// applies to invoices on and after its effective date, never before./// </summary>public sealed class GstRateServiceTests : IDisposable{    private static readonly Guid CompanyId = Guid.NewGuid();    private readonly FakeUnitOfWork _unitOfWork = new();    private readonly GstRateService _rateService;    public GstRateServiceTests()    {        _rateService = new GstRateService(_unitOfWork, new StubCompanyContext(CompanyId));    }    public void Dispose() => _unitOfWork.DisposeAsync().AsTask().GetAwaiter().GetResult();    private async Task<HsnSac> ArrangeAsync()    {        var code = new HsnSac(CompanyId, "84137010");        await _unitOfWork.Repository<HsnSac>().AddAsync(code);        return code;    }    // ---------------------------------------------------------------- C5.5 — effective dates    [Fact]    public async Task Resolve_RateChangedEffectiveFirstJuly_JuneUsesTwelveAndJulyUsesEighteen()    {        var code = await ArrangeAsync();        await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 120_000L, EffectiveFrom: new DateOnly(2026, 4, 1)));        await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 180_000L, EffectiveFrom: new DateOnly(2026, 7, 1)));        var june = await _rateService.ResolveAsync(code.Id, new DateOnly(2026, 6, 30));        var july = await _rateService.ResolveAsync(code.Id, new DateOnly(2026, 7, 1));        june.RatePercentMinor.ShouldBe(120_000L);        july.RatePercentMinor.ShouldBe(180_000L);    }    [Fact]    public async Task Resolve_AddingNewerRow_ClosesOlderOpenEndedRow()    {        var code = await ArrangeAsync();        var first = await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 120_000L, EffectiveFrom: new DateOnly(2026, 4, 1)));        await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 180_000L, EffectiveFrom: new DateOnly(2026, 7, 1)));        var schedules = await _rateService.ListAsync(code.Id);        schedules.Count.ShouldBe(2);        schedules.Single(schedule => schedule.Id == first.Id)            .EffectiveTo.ShouldBe(new DateOnly(2026, 6, 30));    }    [Fact]    public async Task Resolve_DateBeforeAnySchedule_ReturnsZeroRate()    {        var code = await ArrangeAsync();        await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 120_000L, EffectiveFrom: new DateOnly(2026, 4, 1)));        var resolved = await _rateService.ResolveAsync(code.Id, new DateOnly(2025, 12, 31));        resolved.RatePercentMinor.ShouldBe(0L);        resolved.CompensationCessPercentMinor.ShouldBe(0L);    }    [Fact]    public async Task Add_OverlappingSchedule_IsRefused()    {        var code = await ArrangeAsync();        await _rateService.AddAsync(new SaveGstRateScheduleRequest(            code.Id, 120_000L, EffectiveFrom: new DateOnly(2026, 4, 1)));        await Should.ThrowAsync<InvalidOperationException>(async () =>            await _rateService.AddAsync(new SaveGstRateScheduleRequest(                code.Id, 180_000L, EffectiveFrom: new DateOnly(2026, 5, 1))));    }    [Fact]    public async Task Add_UnknownHsnSacId_IsRefused()    {        await Should.ThrowAsync<InvalidOperationException>(async () =>            await _rateService.AddAsync(new SaveGstRateScheduleRequest(                Guid.NewGuid(), 180_000L, EffectiveFrom: new DateOnly(2026, 4, 1))));    }}